  on: {
    event: 'slack:command:/deploy',
  },
  fn: async (input: SlackCommandInput, ctx) => {
    ctx.logger.info(`${input.user_name} ran ${input.command} ${input.text}`);
    return { command: input.command, args: input.text };
  },
});
```

